def transform(grid):
    a=[row[:] for row in grid]
    R,C=len(a),len(a[0])
    blocks=[]
    for r in range(R-2):
        for c in range(C-2):
            color=a[r][c]
            if color and all(a[r+i][c+j]==color for i in range(3) for j in range(3)):
                blocks.append((color,r+1,c+1))
    # extend each 3x3 object's middle row and column; distinct-color crossings are left blank
    lines={}
    for color,r,c in blocks:
        for j in range(C): lines.setdefault((r,j),set()).add(color)
        for i in range(R): lines.setdefault((i,c),set()).add(color)
    for (r,c),colors in lines.items():
        if len(colors)==1: a[r][c]=next(iter(colors))
        elif len(colors)>1: a[r][c]=0
    return a
